struct ListNode { int val; ListNode* next; };

ListNode* reverseList(ListNode* head) {
    ListNode* prev = nullptr;
    while (head != nullptr) {
        ListNode* next = head->next;  // 先保存后继
        head->next = prev;            // 反转当前指针
        prev = head;                  // prev 前移
        head = next;                  // head 前移
    }
    return prev;                      // 新表头
}
```

