int countDegreeOne(int n) {
    int count = 0;
    for (int i = 1; i <= n / 2; ++i) {
        bool hasLeft = (2 * i <= n);
        bool hasRight = (2 * i + 1 <= n);
        if (hasLeft != hasRight) ++count;
    }
    return count;
}
